import { shipOrder } from './src/shipping/domain/shipment.ts';

// Test 1: Pending order can be shipped
const pendingOrder = { id: 'o1', customerId: 'alice', status: 'pending', items: ['sku-1'] };
const shipped = shipOrder(pendingOrder);
console.log('Test 1 - Pending order shipped:', shipped.status === 'shipped' ? '✓' : '✗');

// Test 2: Cancelled order cannot be shipped
const cancelledOrder = { id: 'o2', customerId: 'bob', status: 'cancelled', items: ['sku-2'] };
try {
  shipOrder(cancelledOrder);
  console.log('Test 2 - Cancelled order rejection:', '✗ (should have thrown)');
} catch (e) {
  console.log('Test 2 - Cancelled order rejection:', e.message.includes('cancelled') ? '✓' : '✗');
}

// Test 3: Shipped order stays shipped (edge case)
const shippedOrder = { id: 'o3', customerId: 'charlie', status: 'shipped', items: ['sku-3'] };
const reshipped = shipOrder(shippedOrder);
console.log('Test 3 - Already shipped can be shipped again:', reshipped.status === 'shipped' ? '✓' : '✗');
"

